	private static List<TupleExpr> joinArgs(TupleExpr tupleExpr) {
		List<TupleExpr> args = new ArrayList<>();
		collectJoinArgs(tupleExpr, args);
		return args;
	}

	private static void collectJoinArgs(TupleExpr tupleExpr, List<TupleExpr> args) {
		if (tupleExpr instanceof UnaryTupleOperator unaryTupleOperator) {
			collectJoinArgs(unaryTupleOperator.getArg(), args);
		} else if (tupleExpr instanceof Join join) {
			collectJoinArgs(join.getLeftArg(), args);
			collectJoinArgs(join.getRightArg(), args);
		} else {
			args.add(tupleExpr);
		}
	}

	private static String predicate(TupleExpr tupleExpr) {
		return ((StatementPattern) tupleExpr).getPredicateVar().getValue().stringValue();
	}

	private static boolean isPair(String left, String right, String first, String second) {
		return left.equals(first) && right.equals(second) || left.equals(second) && right.equals(first);
	}

	private static final class ConnectedJoinStatistics extends EvaluationStatistics {

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern) {
				return switch (predicate(tupleExpr)) {
				case "ex:pAnchor" -> 1;
				case "ex:pConnected" -> 10_000;
				case "ex:pDisconnected" -> 10;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(tupleExpr));
				};
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class ConnectedAlternativesStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern) {
				return switch (predicate(tupleExpr)) {
				case "ex:pAnchor" -> 1;
				case "ex:pConnectedCheap" -> 2;
				case "ex:pConnectedExpensive" -> 3;
				case "ex:pDisconnected" -> 100;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(tupleExpr));
				};
			}
			if (tupleExpr instanceof Join join) {
				String left = predicate(join.getLeftArg());
				String right = predicate(join.getRightArg());
				if (isPair(left, right, "ex:pAnchor", "ex:pConnectedCheap")) {
					return 2;
				}
				if (isPair(left, right, "ex:pAnchor", "ex:pConnectedExpensive")) {
					return 3;
				}
				if (isPair(left, right, "ex:pConnectedCheap", "ex:pConnectedExpensive")) {
					return 4;
				}
				return 100;
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class EqualPairwiseStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern) {
				return switch (predicate(tupleExpr)) {
				case "ex:pAnchor" -> 1;
				case "ex:pDisconnected" -> 10;
				case "ex:pConnected" -> 10_000;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(tupleExpr));
				};
			}
			if (tupleExpr instanceof Join) {
				return 5;
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class DisconnectedPairStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern pattern) {
				return switch (predicate(pattern)) {
				case "ex:pFirst" -> 1;
				case "ex:pSecond" -> 2;
				case "ex:pThird" -> 3;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(pattern));
				};
			}
			if (tupleExpr instanceof Join join) {
				String left = predicate(join.getLeftArg());
				String right = predicate(join.getRightArg());
				return isPair(left, right, "ex:pFirst", "ex:pSecond") ? 1 : 100;
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class CheaperCartesianPairStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern) {
				return switch (predicate(tupleExpr)) {
				case "ex:pAnchor" -> 1;
				case "ex:pConnected" -> 10_000;
				case "ex:pDisconnected" -> 10;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(tupleExpr));
				};
			}
			if (tupleExpr instanceof Join join) {
				String left = predicate(join.getLeftArg());
				String right = predicate(join.getRightArg());
				if (isPair(left, right, "ex:pAnchor", "ex:pDisconnected")) {
					return 2;
				}
				if (isPair(left, right, "ex:pConnected", "ex:pDisconnected")) {
					return 3;
				}
				if (isPair(left, right, "ex:pAnchor", "ex:pConnected")) {
					return 100;
				}
				throw new AssertionError("Unexpected join pair: " + left + ", " + right);
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class InheritedBindingJoinStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr tupleExpr) {
			if (tupleExpr instanceof StatementPattern) {
				return switch (predicate(tupleExpr)) {
				case "ex:pOuter" -> 1;
				case "ex:pBound" -> 100;
				case "ex:pConnected" -> 10_000;
				case "ex:pDisconnected" -> 10;
				default -> throw new AssertionError("Unexpected predicate: " + predicate(tupleExpr));
				};
			}
			if (tupleExpr instanceof Join join) {
				String left = predicate(join.getLeftArg());
				String right = predicate(join.getRightArg());
				if (isPair(left, right, "ex:pBound", "ex:pDisconnected")) {
					return 2;
				}
				if (isPair(left, right, "ex:pConnected", "ex:pDisconnected")) {
					return 3;
				}
				if (isPair(left, right, "ex:pBound", "ex:pConnected")) {
					return 100;
				}
				throw new AssertionError("Unexpected join pair: " + left + ", " + right);
			}
			return super.getCardinality(tupleExpr);
		}
	}

	private static final class LateralFinder extends AbstractQueryModelVisitor<RuntimeException> {

		private Lateral lateral;

		@Override
		public void meet(Lateral lateral) {
			this.lateral = lateral;
		}

		private Lateral getLateral() {
			if (lateral == null) {
				throw new AssertionError("Expected a lateral expression");
			}
			return lateral;
		}
	}
